// Contract tests: the static POC API (api/v1, generated by scripts/build-api.mjs)
// must match the proposed OpenAPI contract (docs/api/openapi.yaml).
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { execFileSync } = require("node:child_process");
const L = require("../../src/engine/locations.js");

const ROOT = path.resolve(__dirname, "../..");
execFileSync(process.execPath, [path.join(ROOT, "scripts/build-api.mjs")], { cwd: ROOT, stdio: "ignore" });
const read = (p) => JSON.parse(fs.readFileSync(path.join(ROOT, "api/v1", p), "utf8"));
const spec = fs.readFileSync(path.join(ROOT, "docs/api/openapi.yaml"), "utf8");
const DATA = require("../../data/schemes.json");

const SCHEME_REQUIRED = ["id", "name", "level", "jurisdictions", "category", "criteria", "benefits", "documents", "sources", "verification", "version"];
const CODES = new Set(["ALL", ...L.ALL.map((l) => l.code)]);
const OPS = new Set(["gte", "lte", "gt", "lt", "eq", "in", "notIn", "isTrue", "isFalse", "eduGte", "manual"]);

test("spec declares every path the POC serves", () => {
  for (const p of ["/meta.json", "/schemes/index.json", "/schemes/{id}.json", "/jurisdictions/index.json", "/jurisdictions/{code}/schemes.json", "/changes/index.json"]) {
    assert.ok(spec.includes(`  ${p}:`), p);
  }
  assert.ok(fs.existsSync(path.join(ROOT, "api/v1/openapi.yaml")));
});

test("meta.json matches the Meta schema and the dataset", () => {
  const m = read("meta.json");
  for (const k of ["apiVersion", "schemaVersion", "generatedAt", "count", "publisher", "notice"]) assert.ok(k in m, k);
  assert.equal(m.count, DATA.schemes.length);
  assert.match(m.publisher, /not an official/i);
});

test("schemes collection and per-id resources agree and satisfy the Scheme schema", () => {
  const idx = read("schemes/index.json");
  assert.equal(idx.count, idx.schemes.length);
  for (const s of idx.schemes) {
    for (const k of SCHEME_REQUIRED) assert.ok(k in s, `${s.id}.${k}`);
    assert.match(s.id, /^[a-z0-9-]{1,120}$/);
    assert.ok(["CENTRAL", "STATE", "UNION_TERRITORY"].includes(s.level));
    for (const j of s.jurisdictions) assert.ok(CODES.has(j), j);
    assert.ok(s.sources.length >= 1);
    for (const c of s.criteria) {
      assert.ok(c.id && c.label);
      if (!c.anyOf) assert.ok(OPS.has(c.op), `${s.id}/${c.id} op ${c.op}`);
      assert.ok(c.evidence && typeof c.evidence.quote === "string" && Number.isInteger(c.evidence.source));
    }
    for (const b of s.benefits) assert.ok(b.amount === null || b.amount === undefined || b.amount >= 0);
    assert.deepEqual(read(`schemes/${s.id}.json`), s);
  }
});

test("jurisdictions: 28 States + 8 UTs, and each list is Central + that State/UT only", () => {
  const j = read("jurisdictions/index.json").jurisdictions;
  assert.equal(j.filter((x) => x.type === "STATE").length, 28);
  assert.equal(j.filter((x) => x.type === "UNION_TERRITORY").length, 8);
  const central = DATA.schemes.filter((s) => s.jurisdictions.includes("ALL")).length;
  for (const l of j) {
    const list = read(`jurisdictions/${l.code}/schemes.json`);
    assert.equal(list.count, central + l.schemeCount, l.code);
    for (const s of list.schemes) assert.ok(s.jurisdictions.includes("ALL") || s.jurisdictions.includes(l.code));
  }
});

test("change feed is newest first with added/changed fields", () => {
  const { changes } = read("changes/index.json");
  assert.ok(changes.length >= 1);
  for (const c of changes) assert.ok(c.syncedAt && Array.isArray(c.added) && typeof c.changed === "object");
  const times = changes.map((c) => c.syncedAt);
  assert.deepEqual(times, [...times].sort().reverse());
});

test("API carries no personal data fields", () => {
  const raw = fs.readFileSync(path.join(ROOT, "api/v1/schemes/index.json"), "utf8");
  assert.doesNotMatch(raw, /"(aadhaar|dob|dateOfBirth|mobile|phone|email|profile)"\s*:/i);
});
